 */
@Test
public void testDestroy() throws Exception {
    assertFalse(reader.isDestroyed());
    reader.destroy();
    verify(executorService).shutdownNow();
    verify(sqlServerSnapshot).close();
    assertTrue(reader.isDestroyed());
}

